INSERT INTO faq (q,r,ordre) VALUES ('Comment passer commande ?','Ajoutez vos articles au panier, cliquez sur « Commander », remplissez vos coordonnées : votre commande part directement sur notre WhatsApp. On vous recontacte ensuite pour confirmer les détails (livraison, paiement).',0);
INSERT INTO faq (q,r,ordre) VALUES ('Comment choisir ma taille ?','Chaque fiche produit indique les tailles disponibles. En cas de doute, écrivez-nous sur WhatsApp avec votre taille habituelle, nous vous conseillons.',1);
